From 8c2487c606f1ebfc3516bc028074c71608cf8b06 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:02:19 +0100
Subject: [PATCH] shell/panelview: Keep an auto-hide panel shown when its menu
 closes

Qt sends the panel a Leave when one of its menus grabs the pointer but
no Enter when the menu closes, so clicking on the panel to close a menu
hid it under the pointer. Remember the pointer is still on the panel.

BUG: 464074
---
 shell/panelview.cpp | 14 ++++++++++++--
 shell/panelview.h   |  1 +
 2 files changed, 13 insertions(+), 2 deletions(-)

diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..b713c9d43b 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -6,6 +6,7 @@

 #include <config-plasma.h>

+#include <algorithm>
 #include <chrono>

 #include "autohidescreenedge.h"
@@ -960,7 +961,7 @@ void PanelView::restoreAutoHide()

     if (!edgeActivated()) {
         autoHide = false;
-    } else if (m_containsMouse || m_containsDrag) {
+    } else if (m_containsMouse || m_containsMouseBehindPopup || m_containsDrag) {
         autoHide = false;
     } else if (m_corona->isEditMode()) {
         autoHide = false;
@@ -1175,17 +1176,25 @@ bool PanelView::event(QEvent *e)
         break;
     case QEvent::Enter:
         m_containsMouse = true;
+        m_containsMouseBehindPopup = false;
         if (edgeActivated()) {
             m_unhideTimer.stop();
         }
         break;

-    case QEvent::Leave:
+    case QEvent::Leave: {
+        // Qt sends a Leave when one of our menus grabs the pointer, but no Enter once it closes,
+        // so remember that the pointer is still on the panel until it really leaves it
+        const bool popupOpen = std::ranges::any_of(qApp->topLevelWindows(), [this](QWindow *window) {
+            return window->transientParent() == this && window->type() == Qt::Popup && window->isVisible();
+        });
+        m_containsMouseBehindPopup = m_containsMouse && popupOpen;
         m_containsMouse = false;
         if (edgeActivated()) {
             m_unhideTimer.start();
         }
         break;
+    }

         /*Fitt's law: if the containment has margins, and the mouse cursor clicked
          * on the mouse edge, forward the click in the containment boundaries
@@ -1300,6 +1309,7 @@ bool PanelView::event(QEvent *e)

     case QEvent::Hide: {
         m_containsMouse = false;
+        m_containsMouseBehindPopup = false;
         break;
     }
     default:
diff --git a/shell/panelview.h b/shell/panelview.h
index eb276bf7f6..219cdcae79 100644
--- a/shell/panelview.h
+++ b/shell/panelview.h
@@ -347,6 +347,7 @@ private:
     bool m_floating;
     bool m_floatingApplets;
     bool m_containsMouse = false;
+    bool m_containsMouseBehindPopup = false;
     bool m_containsDrag = false;
     bool m_fakeEventPending = false;
     bool m_touchingWindow = false;
